import base64,hashlib,json,os,pathlib
root=pathlib.Path('/home/qian/hepta-runtime-optimization-20261106-r34')
assert root.resolve(strict=True)==root and root.stat().st_uid==os.getuid()==1000
assert all(not os.path.lexists(root/n) for n in ('source','target-build','qualification-01','preparation.json','cache-prune-01'))
files=json.loads(base64.b64decode('',validate=True))
assert {f['name'] for f in files}=={'prune_cache.py','plan.json'}
directory=root/'cache-prune-tools-01'
directory.mkdir(mode=0o700)
for f in files:
    raw=base64.b64decode(f['data_base64'],validate=True)
    assert len(raw)==f['bytes'] and hashlib.sha256(raw).hexdigest()==f['sha256']
    path=directory/f['name']
    with path.open('xb') as stream:
        stream.write(raw);stream.flush();os.fsync(stream.fileno())
    assert path.read_bytes()==raw
os.execv('/usr/bin/python3',['/usr/bin/python3','-B','-u',str(directory/'prune_cache.py'),'--plan-sha256','0e372a560b119422d41ae29c5b0d2d8c4103cbd95b7f16f3dfe75b1c47d2d256'])
